# --------------------------------------------------------------------------- data migration
# Frozen copy of the snapshot/hash rules in agentos_core.autopilot.config (schema_version 1),
# so this migration keeps producing the same hashes even if the application code evolves.


def _canonical(value: object) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, default=str)


def _backfill_versions() -> None:
    """Every existing agent gets an immutable v1 equal to its current config, marked active,
    plus an 'initial' deployment record. Existing runs keep agent_version_id NULL (their exact
    historical config is unknown), and the executor falls back to the agent row for them."""
    conn = op.get_bind()
    agents = (
        conn.execute(
            sa.text(
                "SELECT id, workspace_id, system_instructions, provider, model, model_configuration, allowed_tool_ids, "
                "max_steps, max_cost_usd, timeout_seconds FROM agent_definitions"
            )
        )
        .mappings()
        .all()
    )
    now = datetime.now(UTC)
    for a in agents:
        snapshot = {
            "schema_version": 1,
            "system_instructions": a["system_instructions"] or "",
            "provider": a["provider"],
            "model": a["model"],
            "model_configuration": dict(a["model_configuration"] or {}),
            "allowed_tool_ids": sorted(set(a["allowed_tool_ids"] or [])),
            "tool_descriptions": {},
            "tool_strategy": "",
            "max_steps": a["max_steps"],
            "max_cost_usd": f"{Decimal(str(a['max_cost_usd'])):.6f}",
            "timeout_seconds": a["timeout_seconds"],
            "retry_max_attempts": None,
        }
        vid = uuid.uuid4()
        conn.execute(
            sa.text(
                "INSERT INTO agent_config_versions (id, workspace_id, agent_id, version, config_snapshot, config_hash, "
                "source, change_summary, created_at) VALUES (:id, :ws, :agent, 1, CAST(:snap AS jsonb), :hash, "
                "'initial', 'Backfilled from the agent definition by migration 0002', :now)"
            ),
            {
                "id": vid,
                "ws": a["workspace_id"],
                "agent": a["id"],
                "snap": json.dumps(snapshot),
                "hash": hashlib.sha256(_canonical(snapshot).encode()).hexdigest(),
                "now": now,
            },
        )
        conn.execute(
            sa.text("UPDATE agent_definitions SET active_version_id = :v WHERE id = :a"),
            {"v": vid, "a": a["id"]},
        )
        conn.execute(
            sa.text(
                "INSERT INTO agent_deployments (id, workspace_id, agent_id, config_version_id, environment, "
                "deployment_type, canary_percent, reason, status, deployed_at) VALUES (:id, :ws, :agent, :v, "
                "'default', 'initial', 100, 'Initial version created by migration 0002', 'active', :now)"
            ),
            {"id": uuid.uuid4(), "ws": a["workspace_id"], "agent": a["id"], "v": vid, "now": now},
        )


IMMUTABLE_TABLES = (
    "agent_config_versions",
    "evaluation_datasets",
    "evaluation_cases",
    "rollout_events",
    "autopilot_events",
)


def _immutability_triggers() -> None:
    """Audit records cannot be rewritten, even by buggy application code."""
    op.execute("""
CREATE OR REPLACE FUNCTION agentos_forbid_change() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'agentos: % on % is not allowed (immutable audit record)', TG_OP, TG_TABLE_NAME
    USING ERRCODE = 'restrict_violation';
END $$ LANGUAGE plpgsql;
""")
    for table in IMMUTABLE_TABLES:
        op.execute(
            f"CREATE TRIGGER {table}_immutable BEFORE UPDATE OR DELETE ON {table} "
            "FOR EACH ROW EXECUTE FUNCTION agentos_forbid_change()"
        )
    # Experiments, evaluation runs and case results are append-then-seal: once completed they are frozen.
    op.execute("""
CREATE OR REPLACE FUNCTION agentos_seal_completed() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'agentos: DELETE on % is not allowed', TG_TABLE_NAME USING ERRCODE = 'restrict_violation';
  END IF;
  IF (TG_TABLE_NAME = 'evaluation_case_results' AND OLD.status = 'graded')
     OR (TG_TABLE_NAME <> 'evaluation_case_results' AND OLD.status IN ('completed','failed','cancelled')) THEN
    RAISE EXCEPTION 'agentos: % is sealed and cannot be modified', TG_TABLE_NAME USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
""")
    for table in ("optimization_experiments", "evaluation_runs", "evaluation_case_results"):
        op.execute(
            f"CREATE TRIGGER {table}_sealed BEFORE UPDATE OR DELETE ON {table} "
            "FOR EACH ROW EXECUTE FUNCTION agentos_seal_completed()"
        )
    # Deployments: only the rollback/supersede bookkeeping columns may change, and never be deleted.
    op.execute("""
CREATE OR REPLACE FUNCTION agentos_deployment_guard() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'agentos: DELETE on agent_deployments is not allowed' USING ERRCODE = 'restrict_violation';
  END IF;
  IF (NEW.agent_id, NEW.config_version_id, NEW.previous_version_id, NEW.deployment_type, NEW.experiment_id,
      NEW.request_id, NEW.approved_by, NEW.deployed_at, NEW.reason, NEW.canary_percent)
     IS DISTINCT FROM
     (OLD.agent_id, OLD.config_version_id, OLD.previous_version_id, OLD.deployment_type, OLD.experiment_id,
      OLD.request_id, OLD.approved_by, OLD.deployed_at, OLD.reason, OLD.canary_percent) THEN
    RAISE EXCEPTION 'agentos: deployment records are immutable except status/rollback fields'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
""")
    op.execute(
        "CREATE TRIGGER agent_deployments_guard BEFORE UPDATE OR DELETE ON agent_deployments "
        "FOR EACH ROW EXECUTE FUNCTION agentos_deployment_guard()"
    )


